#include <iostream>
#include <complex>
std::complex<double> dcomplex(double r, double i) { return std::complex<double>(r,i);}
struct MyClass {
  int data[1000];
  MyClass() { for (int i = 0; i < 1000; ++i) data[i] = i; }
  MyClass(const MyClass& other) { for (int i = 0; i < 1000; ++i) data[i] = other.data[i]; } // Copy constructor
};
MyClass myFunction() {
  MyClass obj;
  return obj;  // NRVO likely to occur
}
int main() {
  MyClass obj = myFunction();
  return 0;
}
